#!/usr/bin/env python3"""Тест для проверки API агентов"""from sqlmodel import Session, selectfrom models.agent import Agent, AgentPublicfrom core.database import enginedef test_agents_api():    """Тестировать получение агентов через модель"""    with Session(engine) as session:        agents = session.exec(select(Agent)).all()        print(f"Найдено {len(agents)} агентов в базе данных:")                for agent in agents:            print(f"\n🔍 Агент: {agent.name}")            print(f"   ID: {agent.id}")            print(f"   Категория: {agent.category}")            print(f"   Описание: {agent.description}")            print(f"   Иконка: {agent.icon_name}")            print(f"   Цвет: {agent.color_class}")                        # Проверяем сериализацию в AgentPublic            agent_public = AgentPublic.model_validate(agent)            print(f"   AgentPublic категория: {agent_public.category}")                        # Проверяем JSON сериализацию            agent_dict = agent_public.model_dump()            print(f"   JSON категория: {agent_dict.get('category')}")if __name__ == "__main__":    test_agents_api()